argv:
curl -sS -m 30 "https://api.openalex.org/works/doi:10.1145/3332165.3347886?select=id,title,publication_year,abstract_inverted_index,cited_by_count,primary_location" | python3 -c "
import json,sys
d=json.load(sys.stdin)
print(\"HTTP 200  title:\", d.get(\"title\"), d.get(\"publication_year\"), \"cited_by\", d.get(\"cited_by_count\"))
idx=d.get(\"abstract_inverted_index\") or {}
if not idx: print(\"(no abstract in OpenAlex)\")
else:
    words=sorted(((pos,w) for w,ps in idx.items() for pos in ps))
    print(\" \".join(w for _,w in words))
"
